  1→import { FretNote, FRET_NOTES } from './note-data';
  2→
  3→describe('FretNote data', () => {
  4→  const NATURAL_NOTES: readonly string[] = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
  5→  const STRING_COUNT = 6;
  6→  const MAX_FRET = 15;
  7→
  8→  // Standard tuning: string 6 (low E) to string 1 (high E)
  9→  // Expected natural notes per string (fret 0-15):
 10→  const expectedNaturalNotes: Record<number, { fret: number; note: string }[]> = {
 11→    6: [ // Low E string: E F . G . A . B C . D . E F . G
 12→      { fret: 0, note: 'E' }, { fret: 1, note: 'F' }, { fret: 3, note: 'G' },
 13→      { fret: 5, note: 'A' }, { fret: 7, note: 'B' }, { fret: 8, note: 'C' },
 14→      { fret: 10, note: 'D' }, { fret: 12, note: 'E' }, { fret: 13, note: 'F' },
 15→      { fret: 15, note: 'G' },
 16→    ],
 17→    5: [ // A string: A . B C . D . E F . G . A . B C
 18→      { fret: 0, note: 'A' }, { fret: 2, note: 'B' }, { fret: 3, note: 'C' },
 19→      { fret: 5, note: 'D' }, { fret: 7, note: 'E' }, { fret: 8, note: 'F' },
 20→      { fret: 10, note: 'G' }, { fret: 12, note: 'A' }, { fret: 14, note: 'B' },
 21→      { fret: 15, note: 'C' },
 22→    ],
 23→    4: [ // D string: D . E F . G . A . B C . D . E F
 24→      { fret: 0, note: 'D' }, { fret: 2, note: 'E' }, { fret: 3, note: 'F' },
 25→      { fret: 5, note: 'G' }, { fret: 7, note: 'A' }, { fret: 9, note: 'B' },
 26→      { fret: 10, note: 'C' }, { fret: 12, note: 'D' }, { fret: 14, note: 'E' },
 27→      { fret: 15, note: 'F' },
 28→    ],
 29→    3: [ // G string: G . A . B C . D . E F . G . A .
 30→      { fret: 0, note: 'G' }, { fret: 2, note: 'A' }, { fret: 4, note: 'B' },
 31→      { fret: 5, note: 'C' }, { fret: 7, note: 'D' }, { fret: 9, note: 'E' },
 32→      { fret: 10, note: 'F' }, { fret: 12, note: 'G' }, { fret: 14, note: 'A' },
 33→    ],
 34→    2: [ // B string: B C . D . E F . G . A . B C . D
 35→      { fret: 0, note: 'B' }, { fret: 1, note: 'C' }, { fret: 3, note: 'D' },
 36→      { fret: 5, note: 'E' }, { fret: 6, note: 'F' }, { fret: 8, note: 'G' },
 37→      { fret: 10, note: 'A' }, { fret: 12, note: 'B' }, { fret: 13, note: 'C' },
 38→      { fret: 15, note: 'D' },
 39→    ],
 40→    1: [ // High E string: E F . G . A . B C . D . E F . G
 41→      { fret: 0, note: 'E' }, { fret: 1, note: 'F' }, { fret: 3, note: 'G' },
 42→      { fret: 5, note: 'A' }, { fret: 7, note: 'B' }, { fret: 8, note: 'C' },
 43→      { fret: 10, note: 'D' }, { fret: 12, note: 'E' }, { fret: 13, note: 'F' },
 44→      { fret: 15, note: 'G' },
 45→    ],
 46→  };
 47→
 48→  it('should export an array of FretNote objects', () => {
 49→    expect(Array.isArray(FRET_NOTES)).toBe(true);
 50→    expect(FRET_NOTES.length).toBeGreaterThan(0);
 51→  });
 52→
 53→  it('should only contain natural notes (C, D, E, F, G, A, B)', () => {
